#include <iterator>
#include <functional>
#include <cassert>
#include <iostream>

int main() {
    static_assert(std::contiguous_iterator<int *>);
    int values[]{3, 7};
    int *position = values;
    assert(*position == 3);
    ++position;
    assert(*position == 7);
    std::cout << "Checks passed\n";
}
